                const normalized = email.trim().toLocaleLowerCase();
                setPeople((current) => [
                  ...current,
                  {
                    email: normalized,
                    name: normalized,
                    role,
                    status: "Invited",
                  },
                ]);
                setOpen(false);
                setEmail("");
                notify({
                  title: "Demo invitation recorded",
                  description: `${normalized} · ${role}. No email was sent.`,
                  tone: "success",
                });
              }}
            >
              <Field.Root
                required
                invalid={error !== null}
                error={error}
                description="Use a fictional email; this example stays in your browser."
              >
                <Field.Label>Teammate email</Field.Label>
                <Field.Control>
                  <Input
                    type="email"
                    value={email}
                    onChange={(event) => {
                      setEmail(event.currentTarget.value);
                      setError(null);
                    }}
                    placeholder="name@example.test"
                  />
                </Field.Control>
              </Field.Root>
              <Field.Root
                required
                description="Type to search the available workspace roles."
              >
                <Field.Label>Workspace role</Field.Label>
                <Field.Control>
                  <Combobox
                    options={roles}
                    value={role}
                    onValueChange={setRole}
                    listLabel="Workspace roles"
                  />
                </Field.Control>
              </Field.Root>
              <Inline gap="sm" wrap>
                <Dialog.Close>Cancel invitation</Dialog.Close>
                <Button type="submit">Record invitation</Button>
              </Inline>
            </Stack>
          </Dialog.Popup>
        </Dialog.Root>
      </Inline>
      <Card>
        <ScrollArea aria-label="Workspace members" axis="horizontal">
          <Table.Root>
            <Table.Caption>Folio demo workspace members</Table.Caption>
            <Table.Header>
              <Table.Row>
                <Table.ColumnHeader>Person</Table.ColumnHeader>
                <Table.ColumnHeader>Role</Table.ColumnHeader>
                <Table.ColumnHeader>Status</Table.ColumnHeader>
              </Table.Row>
            </Table.Header>
            <Table.Body>
              {people.map((person) => (
                <Table.Row key={person.email}>
                  <Table.RowHeader>
                    <Inline gap="sm" wrap>
                      <Avatar
                        alt=""
                        fallback={person.name.slice(0, 1)}
                        size="sm"
                      />
                      <Text>{person.name}</Text>
                    </Inline>
                  </Table.RowHeader>
                  <Table.Cell>{person.role}</Table.Cell>
                  <Table.Cell>
                    <StatusBadge>{person.status}</StatusBadge>
                  </Table.Cell>
                </Table.Row>
              ))}
            </Table.Body>
          </Table.Root>
        </ScrollArea>
      </Card>
    </Stack>
  );
}
